const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const point = ee.Geometry.Point([125.93, -20.59]);
    const aoi = point.buffer(15000); // 15 km radius
    const tzOffsetHours = 8; // AWST (UTC+8)
    // Local 11:00 -> 03:00Z; Local 14:00 -> 06:00Z on 2020-01-14
    const t1Start = ee.Date('2020-01-14T03:00:00Z');
    const t1End = t1Start.advance(1, 'hour');
    const t2Start = ee.Date('2020-01-14T06:00:00Z');
    const t2End = t2Start.advance(1, 'hour');

    // Helper to get stats for a given hour window
    async function getHourStats(start, end, label) {
      let col = ee.ImageCollection('ECMWF/ERA5/HOURLY')
        .filterDate(start, end)
        .select(['total_cloud_cover']);
      let size = await col.size().getInfo();
      // Recovery: if empty, widen to 2-hour window
      if (size === 0) {
        const widenedEnd = ee.Date(start).advance(2, 'hour');
        col = ee.ImageCollection('ECMWF/ERA5/HOURLY')
          .filterDate(start, widenedEnd)
          .select(['total_cloud_cover']);
        size = await col.size().getInfo();
      }
      if (size === 0) {
        console.log(`${label} Images: 0`);
        return {status: 'C1'};
      }
      const img = ee.Image(col.first());
      // Compute pixel count and mean cloud fraction over AOI
      const count = await img.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aoi,
        scale: 3000,
        maxPixels: 1e9
      }).get('total_cloud_cover').getInfo();
      if (!count || count === 0) {
        console.log(`${label} Images: ${size} (Valid px: 0)`);
        return {status: 'C2'};
      }
      const mean = await img.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: aoi,
        scale: 3000,
        maxPixels: 1e9
      }).get('total_cloud_cover').getInfo();
      if (mean === null || isNaN(mean) || mean < 0 || mean > 1) {
        console.log(`${label} Images: ${size} (Mean invalid)`);
        return {status: 'C3'};
      }
      const pct = mean * 100.0;
      console.log(`${label} Images: ${size}`);
      console.log(`${label} Pixels: ${count}, Cloud%: ${pct.toFixed(1)}`);
      return {status: 'OK', mean, pct, count, size};
    }

    console.log(`AOI: (-20.59,125.93) AWST=UTC+8; Date: 2020-01-14`);
    const s11 = await getHourStats(t1Start, t1End, '11:00 LT');
    if (s11.status !== 'OK') {
      console.log(s11.status);
      return;
    }
    const s14 = await getHourStats(t2Start, t2End, '14:00 LT');
    if (s14.status !== 'OK') {
      console.log(s14.status);
      return;
    }

    const delta = (s14.mean - s11.mean) * 100.0;
    console.log(`Δ Cloud% (14h-11h): ${delta.toFixed(1)}`);

    // Final Answer
    if (delta > 0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${String(err).slice(0,200)}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
